export function exemploDoModelo(m: Mod): Record<string, string> {
  const [resp, reg] = RESP[m.area];
  const v: Record<string, string> = { ...BASE_EXEMPLO, resp, regresp: reg };
  if (m.area === 'Contábil' || m.area === 'Gestão') v.funcionario = BASE_EXEMPLO.funcionario;
  for (const c of m.campos) {
    const x = valorExemplo(m, c);
    v[c.n] = x;
  }
  for (const [re, o] of OVERR) if (re.test(m.nome.toLowerCase())) for (const [k, x] of Object.entries(o)) if (m.campos.some(c => c.n === k)) v[k] = x;
  for (const c of m.campos) if (c.t === 'd' && /^\d{4}-\d{2}-\d{2}$/.test(v[c.n])) v[c.n] = v[c.n].split('-').reverse().join('/');
  return v;
}
